import logging


class CellsRegistryEmpty(Exception):
    """Exception raised when cell registry is empty"""
    pass


class CellsNameNotUnique(Exception):
    """Exception raised when cells names are duplicated"""
    pass


class UnknownCellName(Exception):
    """Exception raised when cells names are duplicated"""
    pass


class CellsPool(object):
    """Container to keep cells loaded from configuration file"""

    def __init__(self):
        self.cells_registry = {}
        self.registered_names = []
        self.used_names = []

    def register_cell(self, name, cell_object):
        """
        Put new cell to the container
        :param name: cell name
        :param cell_object:
        """
        if name not in self.registered_names:
            cell_dict = {name: cell_object}
            self.cells_registry.update(cell_dict)
            self.registered_names.append(name)
            logging.info('New cell registered: {}'.format(name))
        else:
            raise CellsNameNotUnique('Cells names have to be unique! Already registered names = {}'.format(self.registered_names))

    def append_used_names(self, name):
        """
        Register new name / alias used in Robot file
        :param name:
        """
        if name in self.used_names:
            raise CellsNameNotUnique('Cells names have to be unique! Already used names = {}, '
                                     'you are trying to use name: {}'.format(self.used_names, name))
        else:
            self.used_names.append(name)

    def get_cell(self, name):
        """
        Return cell with given name from the cells container
        :param name:
        :return: cell object
        """
        if not self.cells_registry:
            raise CellsRegistryEmpty('Cells Registry is empty!')
        if name in self.cells_registry:
            return self.cells_registry[name]
        raise UnknownCellName('{} not recognized, configured cells: {}'.format(name, self.registered_names))

    def release_used_names(self, name, warn=True):
        """
        Release register name / alias used in Robot file
        :param name:
        """
        if name not in self.used_names:
            if warn:
                logging.warn('Cell name {} was not used'.format(name))
            else:
                raise CellsNameNotUnique('Cell names was not used!')
        else:
            self.used_names.remove(name)
